    };

    // Coba window.confirm; jika diblokir/null, langsung eksekusi
    try {
        const confirmed = window.confirm("Nyatakan kelas ini telah selesai? Agen yang sudah RSVP akan dapat mengonfirmasi kehadiran dengan token.");
        if (confirmed) doComplete();
    } catch (e) {
        // Jika confirm() diblokir, langsung jalankan
        doComplete();
    }
};

